// Explicit synthetic controllers for protocol tests. NEVER imported by production source.
import {createWorld} from '../../dist/src/game/world.js';
import {PUBLIC_RULES} from '../../dist/src/adaptive/world-port.js';
export function tiny(){const s=createWorld('meadow');s.player={...s.home};s.bag=1;s.delivered=4;s.energy=80;s.guards=[];s.berries=[];return s;}
export function program(question='完成当前已声明的任务',kinds=['deposit','wait'],extra={}){return {schema:'gs/decision-program/v1',title:'测试生成器的方案，不是自主发现的证据',stages:[{name:'测试阶段',question,hypothesis:'测试夹具假设',groups:['self','objects','history'],ruleIds:['goal','inventory','energy'],kinds,target:null,candidateIds:null,until:[{kind:'delta',field:'delivered',atLeast:1}],maxActions:20,...extra}]};}
export function proposal(p=program()){return {proposals:[{kind:'program',program:p}]};}
export function generator(fn=()=>proposal()){let calls=[];return {id:'synthetic-G-test-only',kind:'mock',calls,async propose(input,signal){calls.push(structuredClone(input));return {output:await fn(input,calls.length,signal)};}};}
export function backend(select){let calls=[];return {id:'synthetic-S-test-only',kind:'mock',calls,async ask(input,signal){calls.push(structuredClone(input));const frame=input.state.evidence.frame;const selected=await select(frame,calls.length,signal,input);const answers={};for(const [id,q]of Object.entries(input.questions)){if(q.type==='choice'){let option=selected===null?'none':'a'+frame.options.findIndex(o=>o.id===selected);if(!Object.hasOwn(q.criteria,option))option='none';answers[id]={type:'choice',choice:option,confidence:1,probabilities:Object.fromEntries(Object.keys(q.criteria).map(x=>[x,x===option?1:0]))};}else if(q.type==='noul'){const cid=q.instructions.candidate.id;answers[id]={type:'noul',noul:cid===selected?1:0};}else {const cid=q.instructions.candidate.id;answers[id]={type:'score',score:cid===selected?6:0};}}return {answers,model:'synthetic-S-test-only'};}};}
export const chooseDeposit=f=>f.kind==='reframe'?f.options[0]?.id??null:f.options.find(o=>o.id.startsWith('deposit:'))?.id??null;
